style.css:
@-moz-document domain("roblox.com"), domain("www.roblox.com") {
html::before {
    content: "";
    position: fixed;
    inset: 0;
    z-index: -1;
    background-image: url("data:image/jpeg;base64,/9j/4AAQSkZJRgABAQAAAQABAAD..."); /* (your forest image here) */
    background-size: cover;
    background-position: center;
    filter: brightness(0.6) blur(3px);
  }

  body {
    background: transparent !important;
  }
}
